    #1 $display("always generate var after %h", gen.g);
    src = 8'h12;
    #1 $display("always concat start %h", {cv2, w2});
    force {cv2, w2} = {src ^ 8'hff, src};
    #1 $display("always concat forced %h", {cv2, w2});
    src = 8'h56;
    #1 $display("always concat follows %h", {cv2, w2});
    #1 $display("always concat written %h", {cv2, w2});
    release {cv2, w2};
    $display("always concat released %h", {cv2, w2});
    #1 $display("always concat settled %h", {cv2, w2});
    src = 8'h9a;
    #1 $display("always concat after %h", {cv2, w2});
    src = 8'h12;
    #1 $display("always net part start %h", wp);
    force wp[5:2] = 4'b1111;
    #1 $display("always net part forced %h", wp);
    src = 8'h40;
    #1 $display("always net part follows %h", wp);
    release wp[5:2];
    #1 $display("always net part released %h", wp);
    src = 8'h12;
    #1 $display("always net bit start %h", wb);
    force wb[7] = 1'b1;
    #1 $display("always net bit forced %h", wb);
    src = 8'h40;
    #1 $display("always net bit follows %h", wb);
    release wb[7];
    #1 $display("always net bit released %h", wb);
    src = 8'h12;
    av = 8'h11;
    #1 $display("always assign start %h", av);
    assign av = src;
    #1 $display("always assign assigned %h", av);
    src = 8'h34;
    #1 $display("always assign follows %h", av);
    av = 8'h55;
    #1 $display("always assign written %h", av);
    force av = 8'haa;
    #1 $display("always assign forced %h", av);
    src = 8'h56;
    #1 $display("always assign forced follows %h", av);
    release av;
    $display("always assign released %h", av);
    #1 $display("always assign reassigned %h", av);
    deassign av;
    src = 8'h78;
    #1 $display("always assign deassigned %h", av);
    av = 8'h99;
    #1 $display("always assign written again %h", av);
    force xv = 8'bx;
    force xb = 8'bx;
    #1 $display("always x %b %b", xv, xb);
    release xv;
    release xb;
  end
endmodule
